/* Champs (ordre des tableaux compacts) */
const FIELDS = ["id","code","forme","activite","raison","cloture","ancienCollab","expertComptable","collaborateur","tenueRevision","delegation","assistant","honoCompta","honoCWE","fraisDoss","honoJuridique","honoOrga","tempsTenueDelegue"];
function arrToObj(a) {
  const o = {};
  FIELDS.forEach((f, i) => (o[f] = a[i]));
  o.statut = "ACTIF";
  o.dateSortie = "";
  o.motifSortie = "";
  return o;
}

const MOTIFS_SORTIE = ["Liquidation judiciaire", "Liquidation amiable", "Arrêt volontaire de mission", "Fin de collaboration", "Autre"];

const FORMES = ["SARL","EURL","SAS","SASU","SCI","EI","E.I.","IND","INDIV","ASS","Monsieur","Madame","Docteur"];
const ACTIVITES = ["SERVICE","NEGOCE","HCR","BATIMENT","MEDICAL","IRPP","SERVICE DAF","SERVICE/NEGOCE"];
const TENUE_OPTS = ["TENUE","REVISION"];
const DELEG_OPTS = ["OUI","NON"];
const MIMIZAN_SET = new Set(["LALUQUE Muriel", "CHAROUD Juline", "KEIGNAERT Chloé", "BERTIN Aurélie"]);

const n = (v) => (typeof v === "number" ? v : 0);
function computeTotals(c) {
  const total = n(c.honoCompta) + n(c.honoCWE) + n(c.fraisDoss) + n(c.honoJuridique) + n(c.honoOrga);
  const valo = 60 * n(c.tempsTenueDelegue);
  const net = n(c.honoCompta) - valo;
  return { total, valo, net };
}
function getSite(collaborateur) {
  if (!collaborateur) return "Non assigné";
  return MIMIZAN_SET.has(collaborateur) ? "MIMIZAN" : "DAX";
}

