const eur = (v) =>
  (v ?? 0).toLocaleString("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: 0 });
const eurK = (v) => {
  const val = v ?? 0;
  if (Math.abs(val) >= 1000) return `${(val / 1000).toLocaleString("fr-FR", { maximumFractionDigits: 0 })} k€`;
  return eur(val);
};

