function SortHeader({ label, field, sort, onSort, align = "left" }) {
  const active = sort.field === field;
  return (
    <th onClick={() => onSort(field)}
      className={`cursor-pointer select-none whitespace-nowrap px-3 py-2.5 text-[11.5px] font-semibold uppercase tracking-wide hover:text-slate-900 ${align === "right" ? "text-right" : "text-left"}`}
      style={{ color: C.muted }}>
      <span className="inline-flex items-center gap-1">
        {label}
        {active && (sort.dir === "asc" ? <ChevronUp size={12} /> : <ChevronDown size={12} />)}
      </span>
    </th>
  );
}

function KpiCard({ icon: Icon, label, value, sub, accent }) {
  return (
    <div className="rounded-md px-4 py-3.5" style={{ background: C.surface, border: `1px solid ${C.border}` }}>
      <p className="flex items-center gap-1.5 text-[11.5px] font-medium uppercase tracking-wide" style={{ color: C.mutedLight }}>
        <Icon size={13} style={{ color: accent || C.navy }} /> {label}
      </p>
      <p className="mt-1 text-[22px] font-semibold tabular-nums" style={{ color: C.text }}>{value}</p>
      {sub && <p className="mt-0.5 text-[11.5px]" style={{ color: C.mutedLight }}>{sub}</p>}
    </div>
  );
}

